614				// 그 뒤의 예산이 통째로 남는다. 여유가 없으면 뻗는 타입을 먼저 쓴다.
615				const bool bMayClose = Frontier.Num() > 2 || WantPassage + WantNormal == 0;
616	
617				TArray<const UCL9ModuleDef*> Pool;
618				int32* Quota = nullptr;
619				bool bStairUp = false;
620				const int32 Choices = StairWant + WantPassage + WantNormal + (bMayClose ? WantDeadEnd : 0);
621				const int32 Roll = Rng.RandRange(0, FMath::Max(Choices, 1) - 1);
622				if (Roll < StairWant)
623				{
624					Pool = StairPool;
625					Quota = &StairWant;
