708		/** 계단 하나를 되돌린다 — 위층 칸을 비우고 그 둘레의 변을 열린 상태로 돌려놓는다 */
709		void DemoteStair(FCL9SiteLayout& Layout, int32 StairIndex, TArray<FFrontier>& UpperFrontier)
710		{
711			FCL9ModulePlacement& Stair = Layout.Modules[StairIndex];
712			const int32 Upper = Stair.Floor + 1;
713			const int32 Base = Upper * Layout.CellStride();
714			for (int32 Y = 0; Y < Stair.Size.Y; ++Y)
715			{
716				for (int32 X = 0; X < Stair.Size.X; ++X)
717				{
718					const FIntPoint Cell(Stair.Origin.X + X, Stair.Origin.Y + Y);
719					Layout.CellModule[Base + Cell.X + Cell.Y * Layout.GridSize.X] = INDEX_NONE;
720					// 위층에서 이 칸 둘레에 뚫렸던 문(고리)도 같이 지운다 — 빈 칸 사이에 문이 남으면
721					// 허공에 문짝이 선다.
722					for (int32 Side = 0; Side < 4; ++Side)
723					{
724						SetEdge(Layout, Upper, Cell, Side, ECL9GridEdge::Open);
725					}
726				}
727			}
728			Stair.bStairUp = false;
729			UpperFrontier.RemoveAll([StairIndex](const FFrontier& Entry) { return Entry.Module == StairIndex; });
730		}
731	
732		/**
733		 * 층 Floor에 선 계단마다 **위층을 먼저 틔운다.** 계단 하나가 자기 둘레에 StairMinReach개
734		 * 이상의 모듈을 이어 붙이지 못하면 그 시도를 통째로 무르고 계단을 되돌린다. 살아남은
735		 * 계단 수를 돌려주고, 위층에 쓴 모듈 수만큼 UpperBudget을 깎는다.
736		 *
737		 * 무르기는 배치 직전의 칸·변·프론티어를 통째로 복사해 두었다가 되돌리는 방식이다 —
738		 * 격자가 22×22 정도라 복사 비용이 없다시피 하고, 되돌린 뒤의 상태가 정확하다.
739		 */
740		int32 SecureStairs(FCL9SiteLayout& Layout, const FCL9SiteParams& Params, int32 Floor, int32& UpperBudget,
741			const TArray<const UCL9ModuleDef*>* Pools, TArray<TArray<FFrontier>>& Frontiers, FRandomStream& Rng)
742		{
743			const int32 Upper = Floor + 1;
744			if (!Layout.IsFloor(Upper))
745			{
746				return 0;
747			}
748	
749			// 위층 첫 방들은 방(Normal)과 복도(Passage)로만 틔운다 — 막다른 방으로 시작하면
750			// 계단을 올라와서 곧장 막힌다.
751			TArray<const UCL9ModuleDef*> RoomPool = Pools[static_cast<int32>(ECL9ModuleType::Normal)];
752			RoomPool.Append(Pools[static_cast<int32>(ECL9ModuleType::Passage)]);
753	
754			TArray<int32> Stairs;
755			for (int32 Index = 0; Index < Layout.Modules.Num(); ++Index)
756			{
757				if (Layout.Modules[Index].bStairUp && Layout.Modules[Index].Floor == Floor)
758				{
759					Stairs.Add(Index);
760				}
761			}
762	
763			int32 Survivors = 0;
764			for (int32 StairIndex : Stairs)
765			{
766				// 예산이 최소치에도 못 미치면 남은 계단은 전부 되돌린다
767				if (UpperBudget < StairMinReach)
768				{
769					DemoteStair(Layout, StairIndex, Frontiers[Upper]);
770					continue;
771				}
772	
773				const TArray<int32> SavedCells = Layout.CellModule;
774				const TArray<uint8> SavedEdgeX = Layout.EdgeX;
775				const TArray<uint8> SavedEdgeY = Layout.EdgeY;
776				const TArray<FFrontier> SavedFrontier = Frontiers[Upper];
777				const int32 SavedModules = Layout.Modules.Num();
778	
779				// 이 계단에서 이어진 모듈들 — 프론티어 중 이 무리에서 나온 것만 골라 뻗는다
780				TSet<int32> Region;
781				Region.Add(StairIndex);
782				int32 Placed = 0;
783				int32 Stall = 0;
784				while (Placed < StairMinReach && Stall < StallLimit)
785				{
786					TArray<int32> Mine;
787					for (int32 Index = 0; Index < Frontiers[Upper].Num(); ++Index)
788					{
789						if (Region.Contains(Frontiers[Upper][Index].Module))
790						{
791							Mine.Add(Index);
792						}
793					}
794					if (Mine.Num() == 0)
795					{
796						break;
797					}
798					const int32 Pick = Mine[Rng.RandRange(0, Mine.Num() - 1)];
799					const FFrontier Spot = Frontiers[Upper][Pick];
800					Frontiers[Upper].RemoveAtSwap(Pick, EAllowShrinking::No);
801	
802					const FIntPoint Target = Spot.Cell + SideDir[Spot.Side];
803					if (!Layout.IsInside(Target) || Layout.CellAt(Upper, Target) != INDEX_NONE)
804					{
805						continue;
806					}
807					if (PlaceAt(Layout, Upper, Spot, RoomPool, /*bStairUp*/ false, Frontiers, Params.LoopChance, Rng))
808					{
809						Region.Add(Layout.Modules.Num() - 1);
810						++Placed;
811						Stall = 0;
812					}
813					else
814					{
815						++Stall;
816					}
817				}
818	
819				if (Placed >= StairMinReach)
820				{
821					UpperBudget -= Placed;
822					++Survivors;
823					continue;
824				}
825	
826				// 못 틔웠다 — 시도 전으로 되돌리고 계단을 내린다
827				Layout.CellModule = SavedCells;
828				Layout.EdgeX = SavedEdgeX;
829				Layout.EdgeY = SavedEdgeY;
830				Frontiers[Upper] = SavedFrontier;
831				Layout.Modules.SetNum(SavedModules);
832				DemoteStair(Layout, StairIndex, Frontiers[Upper]);
833			}
834			return Survivors;
835		}
836	}
