838	FCL9SiteLayout CL9SiteLayout::Generate(const FCL9SiteParams& Params, const TArray<const UCL9ModuleDef*>& Modules, uint32 Seed)
839	{
840		FCL9SiteLayout Layout;
841		Layout.Seed = Seed;
842		if (Seed == 0 || Modules.Num() == 0 || Params.ModuleCount < 2)
843		{
844			return Layout;
845		}
846	
847		// 타입별 후보 묶음. 시작 모듈이 없으면 붙일 곳이 없어서 한 발도 못 뗀다.
848		TArray<const UCL9ModuleDef*> Pools[CL9ModuleTypeCount];
849		for (const UCL9ModuleDef* Def : Modules)
850		{
851			Pools[static_cast<int32>(Def->Type)].Add(Def);
852		}
853		const TArray<const UCL9ModuleDef*>& StartPool = Pools[static_cast<int32>(ECL9ModuleType::Start)];
854		if (StartPool.Num() == 0)
855		{
856			return Layout;
857		}
858	
859		// 계단 모듈이 한 행도 없으면 위층으로 올라갈 방법이 없다 — 단층으로 짓는다.
860		const bool bCanClimb = Pools[static_cast<int32>(ECL9ModuleType::Stair)].Num() > 0;
861		Layout.FloorCount = bCanClimb ? FMath::Clamp(Params.MaxFloors, 1, 8) : 1;
862	
863		// 격자는 모듈이 사방으로 퍼질 만큼만 잡는다 — 너무 크면 배치가 흩어지고,
864		// 너무 작으면 후보가 자꾸 격자 밖으로 떨어져 판이 짧아진다.
865		// 상한 128은 큰 판(farm 200모듈 → 70칸)이 64에 눌리지 않게 (2026-10-03) — 양계장은 36칸 이하라 그대로다.
866		const int32 Span = FMath::Clamp(FMath::CeilToInt(FMath::Sqrt(Params.ModuleCount * 6.f)) * 2, 16, 128);
867		Layout.GridSize = FIntPoint(Span, Span);
868		Layout.CellModule.Init(INDEX_NONE, Layout.FloorCount * Span * Span);
869		Layout.EdgeX.Init(static_cast<uint8>(ECL9GridEdge::Open), Layout.FloorCount * (Span + 1) * Span);
870		Layout.EdgeY.Init(static_cast<uint8>(ECL9GridEdge::Open), Layout.FloorCount * Span * (Span + 1));
871		Layout.Origin = FVector2D(Params.EntryOffset, -Span * Params.CellSize * 0.5f);
872	
873		FRandomStream Rng(static_cast<int32>(Seed));
874	
875		// ---- 시작 모듈: 서쪽 변이 트럭 쪽으로 열리도록 회전을 고르고 격자 서쪽 끝에 붙인다
876		TArray<FCandidate> StartCandidates;
877		for (const UCL9ModuleDef* Def : StartPool)
878		{
879			for (int32 Rotation = 0; Rotation < 4; ++Rotation)
880			{
881				const uint8 Sockets = UCL9ModuleDef::RotateSockets(static_cast<uint8>(Def->Sockets & 0xF), Rotation);
882				if (!HasSide(Sockets, SideW))
883				{
884					continue;
885				}
886				const FIntPoint Size = UCL9ModuleDef::RotateSize(Def->Size, Rotation);
887				FCandidate Cand;
888				Cand.Def = Def;
889				Cand.Origin = FIntPoint(0, (Span - Size.Y) / 2);
890				Cand.Size = Size;
891				Cand.Rotation = Rotation;
892				Cand.Sockets = Sockets;
893				if (Fits(Layout, 0, Cand.Origin, Cand.Size) && !StartCandidates.ContainsByPredicate([&Cand](const FCandidate& Other) { return Cand.SameOutcome(Other); }))
894				{
895					StartCandidates.Add(Cand);
896				}
897			}
898		}
899		const FCandidate* StartPick = PickCandidate(StartCandidates, Rng);
900		if (StartPick == nullptr)
901		{
902			return Layout;
903		}
904	
905		const int32 StartIndex = Occupy(Layout, *StartPick, 0, /*Floor*/ 0, /*bStairUp*/ false);
906		Layout.EntryCell = FIntPoint(StartPick->Origin.X, StartPick->Origin.Y + StartPick->Size.Y / 2);
907		// 입구 문은 격자 바깥으로 난다 — 트럭은 밖에 있고 걸어 들어온다 (module.md 결정 6)
908		SetEdge(Layout, 0, Layout.EntryCell, SideW, ECL9GridEdge::Door);
